// Banco de questoes - Ciencias (Materia e Energia) - 5o ano - prova 25/11
window.BANCO = window.BANCO || {};
window.BANCO.ciencias = [
{n:"f",t:"Formas de energia",q:"Qual é a principal fonte de energia do planeta Terra?",a:["O Sol","A Lua","O petróleo","As pilhas"],c:0,e:"O Sol ilumina e aquece a Terra todos os dias ☀️. Sem a energia dele não haveria plantas, chuva nem vento."},
{n:"f",t:"Formas de energia",q:"Que tipo de energia está guardada nos alimentos?",a:["Energia elétrica","Energia química","Energia sonora","Energia luminosa"],c:1,e:"Os alimentos guardam energia química. Quando comemos, o corpo usa essa energia para crescer, brincar e se manter aquecido 🍎."},
{n:"f",t:"Formas de energia",q:"Que forma de energia nós percebemos com os ouvidos?",a:["Energia térmica","Energia luminosa","Energia sonora","Energia química"],c:2,e:"A energia sonora é o som! Ela é produzida quando algo vibra, como as cordas de um violão 🎸, e chega até os nossos ouvidos."},
{n:"f",t:"Formas de energia",q:"Uma bola rolando no campo tem qual tipo de energia?",a:["Energia luminosa","Energia elétrica","Energia química","Energia de movimento"],c:3,e:"Tudo que está se movendo tem energia de movimento (também chamada de energia cinética). Quanto mais rápida a bola, mais energia de movimento ela tem ⚽."},
{n:"f",t:"Formas de energia",q:"Que forma de energia nos aquece quando ficamos perto de uma fogueira?",a:["Energia térmica","Energia sonora","Energia elétrica","Energia de posição"],c:0,e:"A fogueira libera energia térmica, que sentimos como calor 🔥. Ela também solta luz, mas é o calor que nos aquece."},
{n:"f",t:"Formas de energia",q:"Qual destas é uma fonte de energia renovável, que não se esgota?",a:["O petróleo","O vento","O carvão mineral","O gás natural"],c:1,e:"O vento não acaba: ele sempre volta a soprar 🌬️. Petróleo, carvão mineral e gás natural levam milhões de anos para se formar e podem se esgotar."},
{n:"f",t:"Formas de energia",q:"Qual destas fontes de energia é NÃO renovável?",a:["A luz do Sol","A água dos rios","O petróleo","O vento"],c:2,e:"O petróleo, de onde vem a gasolina, levou milhões de anos para se formar. Se usarmos tudo, ele acaba. Sol, vento e água dos rios se renovam na natureza."},
{n:"f",t:"Formas de energia",q:"A água parada no alto de uma represa guarda energia por causa da sua...",a:["Cor azulada","Temperatura baixa","Transparência da água","Posição no alto"],c:3,e:"Tudo que está no alto guarda energia de posição (energia potencial). Quando a água desce da represa, essa energia vira energia de movimento 💧."},
{n:"f",t:"Formas de energia",q:"De acordo com a ciência, o que acontece com a energia quando a usamos?",a:["Ela se transforma em outras formas","Ela some para sempre","Ela é criada do nada pelas máquinas e aparelhos","Ela volta para a tomada"],c:0,e:"A energia não se cria nem se perde: ela se transforma! A energia da pilha, por exemplo, vira luz e um pouco de calor na lanterna 🔦."},
{n:"f",t:"Formas de energia",q:"Qual forma de energia nos permite enxergar as coisas?",a:["Energia sonora","Energia luminosa","Energia química","Energia elétrica"],c:1,e:"A energia luminosa é a luz. Sem luz, não conseguimos enxergar nada, nem mesmo um objeto bem na nossa frente 👀."},
{n:"f",t:"Transformações de energia",q:"Uma lâmpada acesa transforma energia elétrica principalmente em...",a:["Som e movimento","Energia química","Luz e calor","Energia de posição"],c:2,e:"A lâmpada recebe energia elétrica e a transforma em luz 💡. Ela também esquenta um pouco, então parte da energia vira calor."},
{n:"f",t:"Transformações de energia",q:"Um ventilador ligado transforma energia elétrica principalmente em...",a:["Energia luminosa","Energia química","Energia nuclear","Energia de movimento"],c:3,e:"As hélices do ventilador giram: a energia elétrica virou energia de movimento, que empurra o ar em nossa direção 🌀."},
{n:"f",t:"Transformações de energia",q:"Na lanterna, a pilha transforma energia química em energia...",a:["Elétrica","Sonora","Eólica","De posição"],c:0,e:"A pilha guarda energia química. Ao ligar a lanterna, ela se transforma em energia elétrica, que depois acende a lâmpada 🔋."},
{n:"f",t:"Transformações de energia",q:"Na fotossíntese, que energia as plantas usam para produzir o próprio alimento?",a:["Energia sonora dos pássaros","Energia luminosa do Sol","Energia elétrica","Energia do vento"],c:1,e:"As plantas captam a luz do Sol com as folhas verdes e fabricam seu alimento. Assim, a energia luminosa vira energia química guardada na planta 🌿."},
{n:"f",t:"Transformações de energia",q:"Um rádio ligado transforma energia elétrica principalmente em energia...",a:["Luminosa","Química","Sonora","De posição"],c:2,e:"O rádio transforma energia elétrica em som 📻. É assim que ouvimos música e notícias."},
{n:"f",t:"Transformações de energia",q:"No fogão a gás, a energia química do gás se transforma principalmente em...",a:["Energia elétrica","Energia sonora","Energia de posição","Energia térmica"],c:3,e:"Quando o gás queima, a energia química dele vira calor (e um pouco de luz, na chama azul 🔥). É esse calor que cozinha a comida."},
{n:"f",t:"Transformações de energia",q:"Qual aparelho transforma energia elétrica em calor para esquentar a água do banho?",a:["O chuveiro elétrico","O ventilador","O rádio","A lanterna"],c:0,e:"O chuveiro elétrico tem uma peça chamada resistência, que esquenta quando a eletricidade passa por ela. É energia elétrica virando calor 🚿."},
{n:"f",t:"Transformações de energia",q:"Quando corremos e brincamos, de onde vem a energia que o nosso corpo usa?",a:["Da luz da lâmpada","Dos alimentos","Do som da música","Da água que bebemos"],c:1,e:"A energia química dos alimentos vira energia de movimento quando corremos, e também calor, que mantém o corpo quentinho 🏃. A água é muito importante, mas não fornece energia."},
{n:"f",t:"Transformações de energia",q:"Uma usina hidrelétrica transforma o movimento da água em energia...",a:["Química","Sonora","Elétrica","Luminosa"],c:2,e:"Na hidrelétrica, a água em movimento gira as turbinas, e um gerador transforma esse movimento em eletricidade ⚡."},
{n:"f",t:"Transformações de energia",q:"O painel solar no telhado transforma a luz do Sol em energia...",a:["Sonora","Química","De posição","Elétrica"],c:3,e:"O painel solar (placa fotovoltaica) capta a luz do Sol e a transforma em eletricidade para a casa ☀️⚡."},
{n:"f",t:"Transformações de energia",q:"Um liquidificador ligado transforma energia elétrica em movimento e também em...",a:["Som (barulho)","Luz forte","Energia química","Energia de posição"],c:0,e:"As lâminas do liquidificador giram (movimento) e fazem bastante barulho, que é energia sonora 🔊."},
{n:"f",t:"Transformações de energia",q:"Ao esfregar as mãos uma na outra bem rápido, o movimento se transforma em...",a:["Luz","Calor","Som alto","Eletricidade"],c:1,e:"O atrito entre as mãos transforma movimento em calor. É por isso que esfregamos as mãos num dia frio 🤲."},
{n:"f",t:"Energia luminosa",q:"Qual destes é uma fonte NATURAL de luz?",a:["A lâmpada","A lanterna","O Sol","A vela"],c:2,e:"O Sol é uma fonte natural de luz: não foi feito pelas pessoas. Lâmpada, lanterna e vela são fontes artificiais, criadas pelo ser humano."},
{n:"f",t:"Energia luminosa",q:"Qual destes é uma fonte ARTIFICIAL de luz?",a:["O vaga-lume","O Sol","As estrelas","A lâmpada"],c:3,e:"A lâmpada foi inventada pelas pessoas, por isso é uma fonte artificial de luz 💡. Sol, estrelas e vaga-lumes são fontes naturais."},
{n:"f",t:"Energia luminosa",q:"A Lua brilha no céu à noite porque...",a:["Reflete a luz do Sol","Produz a própria luz","É feita de fogo","Tem lâmpadas por dentro"],c:0,e:"A Lua não tem luz própria: ela é um corpo iluminado. A luz que vemos é a luz do Sol que bate nela e é refletida 🌙."},
{n:"f",t:"Energia luminosa",q:"Como a luz se propaga (viaja)?",a:["Em zigue-zague","Em linha reta","Fazendo curvas","Só de cima para baixo"],c:1,e:"A luz viaja em linha reta. Repare nos raios de sol entrando pela janela ou na luz de uma lanterna: parecem varetas retinhas!"},
{n:"f",t:"Energia luminosa",q:"A sombra se forma quando...",a:["A luz passa por um vidro","A luz fica mais forte","Um objeto opaco bloqueia a luz","O objeto é transparente"],c:2,e:"Quando um objeto que não deixa a luz passar fica no caminho dela, forma-se atrás dele uma região escura: a sombra 👤."},
{n:"f",t:"Energia luminosa",q:"Um material que deixa a luz passar e permite ver nitidamente através dele é chamado de...",a:["Opaco","Translúcido","Refletor de luz","Transparente"],c:3,e:"Materiais transparentes, como o vidro da janela, a água limpa e o ar, deixam a luz passar, e a gente enxerga bem através deles 🪟."},
{n:"f",t:"Energia luminosa",q:"Qual destes materiais é opaco, ou seja, não deixa a luz passar?",a:["A porta de madeira","O vidro da janela","O plástico transparente","O ar"],c:0,e:"A madeira é opaca: bloqueia a luz e não dá para ver o que está do outro lado. Vidro, plástico transparente e ar deixam a luz passar."},
{n:"f",t:"Energia luminosa",q:"O vidro fosco do box do banheiro deixa passar parte da luz, mas não dá para ver bem através dele. Ele é...",a:["Transparente","Translúcido","Opaco","Luminoso"],c:1,e:"Materiais translúcidos deixam passar só parte da luz e embaçam a imagem, como o vidro fosco e o papel vegetal."},
{n:"f",t:"Energia luminosa",q:"Que objeto usamos para ver nossa imagem refletida?",a:["Um pedaço de papelão","Uma folha de jornal","Um espelho","Uma toalha"],c:2,e:"O espelho é uma superfície lisa e polida que reflete a luz. Por isso vemos nossa imagem nele 🪞."},
{n:"f",t:"Energia luminosa",q:"O arco-íris aparece no céu quando a luz do Sol atravessa...",a:["As nuvens escuras","As folhas das árvores","As asas dos pássaros","As gotas de chuva"],c:3,e:"Quando a luz branca do Sol atravessa as gotinhas de chuva, ela se separa em várias cores e forma o arco-íris 🌈."},
{n:"f",t:"Energia térmica e calor",q:"Qual instrumento usamos para medir a temperatura?",a:["Termômetro","Fita métrica","Balança","Relógio"],c:0,e:"O termômetro mede a temperatura, ou seja, o quanto algo está quente ou frio 🌡️."},
{n:"f",t:"Energia térmica e calor",q:"Qual unidade usamos no Brasil para medir a temperatura?",a:["Quilômetro por hora (km/h)","Graus Celsius (°C)","Metro (m)","Litro (L)"],c:1,e:"No Brasil, a temperatura é medida em graus Celsius (°C). Por exemplo: um dia gostoso pode estar a 25 °C."},
{n:"f",t:"Energia térmica e calor",q:"O calor sempre passa...",a:["Do corpo mais frio para o mais quente","Só do Sol para a Terra","Do corpo mais quente para o mais frio","Só de um metal para outro metal"],c:2,e:"Calor é energia térmica em movimento, e ela sempre vai do mais quente para o mais frio. Por isso uma xícara de chocolate quente aquece as nossas mãos ☕."},
{n:"f",t:"Energia térmica e calor",q:"Qual destas é uma fonte de calor?",a:["Uma pedra de gelo","Um copo de suco gelado","Um picolé","Uma fogueira"],c:3,e:"A fogueira libera muito calor quando a madeira queima 🔥. Gelo, suco gelado e picolé não aquecem nada; eles é que recebem calor."},
{n:"f",t:"Energia térmica e calor",q:"Quando a previsão do tempo diz que a temperatura vai estar alta, o dia vai estar...",a:["Quente","Frio","Chuvoso","Escuro"],c:0,e:"Temperatura alta quer dizer tempo quente! Um dia de 35 °C, por exemplo, é bem quente ☀️."},
{n:"f",t:"Energia térmica e calor",q:"Qual é, aproximadamente, a temperatura normal do corpo de uma pessoa saudável?",a:["Cerca de 0 °C, como o gelo","Cerca de 36 a 37 °C","Cerca de 50 °C","Cerca de 100 °C"],c:1,e:"Nosso corpo fica por volta de 36 a 37 °C. Quando a temperatura passa disso, pode ser febre 🤒."},
{n:"f",t:"Energia térmica e calor",q:"Um café quente deixado na mesa esfria porque...",a:["Ele produz frio sozinho","O frio do ar entra no café","Ele perde calor para o ambiente","A mesa sopra ar frio"],c:2,e:"O café está mais quente que o ar e a xícara, então o calor sai dele para o ambiente. O frio não entra: é o calor que sai! ☕"},
{n:"f",t:"Energia térmica e calor",q:"Quando seguramos um cubo de gelo, nossa mão fica fria porque...",a:["O frio do gelo passa para a mão","O gelo produz frio","A mão produz gelo","A mão perde calor para o gelo"],c:3,e:"O frio não passa de um lugar para outro: é o calor que sai! O calor da nossa mão vai para o gelo, por isso a mão esfria e o gelo derrete 🧊."},
{n:"f",t:"Energia térmica e calor",q:"O que acontece com a temperatura da água quando colocamos a panela no fogo?",a:["Ela aumenta","Ela diminui","Ela fica sempre igual","Ela vira zero"],c:0,e:"O fogo passa calor para a panela e para a água. Com isso, a temperatura da água vai subindo 🔥."},
{n:"f",t:"Energia térmica e calor",q:"Num dia frio, por que gostamos de ficar perto de uma lareira acesa?",a:["Porque ela recebe o nosso calor","Porque ela nos passa calor","Porque ela produz frio","Porque ela faz barulho"],c:1,e:"A lareira está bem mais quente que o nosso corpo, então o calor passa dela para nós e ficamos aquecidos 🔥."},
{n:"f",t:"Efeitos do calor",q:"Quando o gelo derrete e vira água líquida, essa mudança de estado se chama...",a:["Condensação","Solidificação","Fusão","Ebulição"],c:2,e:"Fusão é a passagem do estado sólido para o líquido. O gelo recebe calor e derrete, virando água 💧."},
{n:"f",t:"Efeitos do calor",q:"Quando a água vira gelo no congelador, essa mudança de estado se chama...",a:["Fusão","Evaporação","Condensação","Solidificação"],c:3,e:"Solidificação é a passagem do líquido para o sólido. No congelador, a água perde calor e vira gelo 🧊."},
{n:"f",t:"Efeitos do calor",q:"A que temperatura a água pura ferve ao nível do mar?",a:["100 °C","1.000 °C","0 °C","37 °C"],c:0,e:"Ao nível do mar, a água pura ferve a 100 °C. É a temperatura da água borbulhando na chaleira!"},
{n:"f",t:"Efeitos do calor",q:"A que temperatura a água pura congela (e o gelo derrete)?",a:["10 °C","0 °C","100 °C","37 °C"],c:1,e:"A água congela a 0 °C, e o gelo derrete nessa mesma temperatura. Abaixo disso, a água vira gelo ❄️."},
{n:"f",t:"Efeitos do calor",q:"A roupa molhada seca no varal porque a água...",a:["Congela","Derrete","Evapora","Condensa"],c:2,e:"A água da roupa vai virando vapor aos poucos, sem ferver. Isso é a evaporação, que é mais rápida com sol e vento 👕."},
{n:"f",t:"Efeitos do calor",q:"Depois de um banho quente, o espelho do banheiro fica embaçado de gotinhas. Que mudança de estado aconteceu?",a:["Fusão","Solidificação","Evaporação","Condensação"],c:3,e:"O vapor quente do banho encosta no espelho frio, perde calor e vira gotinhas de água: é a condensação 🚿."},
{n:"f",t:"Efeitos do calor",q:"Os trilhos de trem são instalados com pequenos espaços (folgas) entre eles porque, no calor, o metal...",a:["Dilata, ficando maior","Encolhe bastante","Derrete e escorre todo","Fica mais leve"],c:0,e:"Com o calor, o metal dilata (aumenta um pouquinho de tamanho). Sem as folgas, os trilhos se empurrariam e poderiam entortar 🚆."},
{n:"f",t:"Efeitos do calor",q:"Em geral, o que acontece com os materiais quando são aquecidos?",a:["Contraem (diminuem de tamanho)","Dilatam (aumentam de tamanho)","Mudam de cor sempre","Ficam mais pesados"],c:1,e:"Quando aquecidos, os materiais dilatam: aumentam um pouquinho de tamanho. Quando esfriam, eles contraem (diminuem)."},
{n:"f",t:"Efeitos do calor",q:"O que acontece com um cubo de gelo deixado fora do congelador num dia quente?",a:["Fica mais gelado","Vira vapor de água na mesma hora","Recebe calor e derrete","Fica cada vez maior"],c:2,e:"O ambiente está mais quente que o gelo, então o gelo recebe calor e derrete, virando água líquida (fusão) 💧."},
{n:"f",t:"Efeitos do calor",q:"Quando a água ferve na panela e forma muitas bolhas, essa mudança de estado se chama...",a:["Condensação","Fusão","Solidificação","Ebulição"],c:3,e:"A ebulição acontece quando a água ferve: surgem bolhas de vapor e ela vira gás rapidamente. Ao nível do mar, isso ocorre a 100 °C."},
{n:"f",t:"Condutores e isolantes de calor",q:"Qual destes materiais é um bom condutor de calor?",a:["Metal","Madeira","Isopor","Lã"],c:0,e:"Os metais deixam o calor passar com facilidade. Por isso as panelas são de metal e esquentam rápido no fogo 🍳."},
{n:"f",t:"Condutores e isolantes de calor",q:"Por que o cabo de muitas panelas é de madeira ou de plástico?",a:["Para a panela ficar mais bonita","Porque são isolantes de calor","Porque conduzem muito bem o calor","Para a panela pesar mais"],c:1,e:"Madeira e plástico são isolantes: o calor passa por eles com dificuldade. Assim, o cabo não esquenta tanto e podemos segurar a panela 👍."},
{n:"f",t:"Condutores e isolantes de calor",q:"Qual material é muito usado nas caixas térmicas para manter as bebidas geladas?",a:["Alumínio","Ferro","Isopor","Cobre"],c:2,e:"O isopor é um ótimo isolante: dificulta a entrada do calor de fora, e as bebidas continuam geladas por mais tempo 🧊."},
{n:"f",t:"Condutores e isolantes de calor",q:"Por que muitas panelas são feitas de metal, como o alumínio?",a:["Porque o metal é isolante","Porque o metal não esquenta","Porque o metal é transparente como vidro","Porque o metal conduz bem o calor"],c:3,e:"O metal é bom condutor: leva o calor do fogo até a comida rapidinho. Por isso as panelas são de alumínio, aço ou ferro 🍲."},
{n:"f",t:"Condutores e isolantes de calor",q:"No inverno usamos casaco de lã. O que o casaco faz?",a:["Segura o calor do nosso corpo","Fabrica calor sozinho","Produz frio","Puxa o frio para longe"],c:0,e:"O casaco não produz calor! A lã é isolante e dificulta a saída do calor do nosso corpo. Quem produz o calor somos nós 🧥."},
{n:"f",t:"Condutores e isolantes de calor",q:"Para que serve a luva de cozinha de tecido grosso?",a:["Esquentar a comida","Proteger a mão do calor da forma","Deixar a forma quente mais leve","Esfriar o forno por dentro"],c:1,e:"O tecido grosso da luva é isolante: o calor da forma quente passa para a mão bem devagar, e assim não nos queimamos 🧤."},
{n:"f",t:"Condutores e isolantes de calor",q:"Materiais que deixam o calor passar com facilidade são chamados de...",a:["Isolantes térmicos","Materiais transparentes","Condutores térmicos","Materiais opacos"],c:2,e:"Condutores térmicos deixam o calor passar com facilidade, como os metais. Isolantes térmicos dificultam a passagem, como a madeira, o isopor e a lã."},
{n:"f",t:"Condutores e isolantes de calor",q:"Qual destes materiais é um isolante térmico?",a:["Cobre","Alumínio","Ferro","Isopor"],c:3,e:"O isopor tem muitas bolinhas de ar presas, o que dificulta a passagem do calor. Cobre, alumínio e ferro são metais e conduzem bem o calor."},
{n:"f",t:"Condutores e isolantes de calor",q:"Para que serve uma garrafa térmica?",a:["Manter o café quente por mais tempo","Ferver a água sozinha","Gelar a bebida mais rápido que a geladeira","Esquentar o café que está frio"],c:0,e:"A garrafa térmica dificulta a passagem do calor. Assim, o café quente demora muito para esfriar ☕, e um suco gelado também fica gelado por mais tempo."},
{n:"f",t:"Condutores e isolantes de calor",q:"Se deixarmos uma colher de metal numa xícara de chocolate quente, o cabo da colher...",a:["Fica gelado","Esquenta","Derrete","Congela"],c:1,e:"O metal é bom condutor de calor: o calor do chocolate sobe pela colher até o cabo. Cuidado para não se queimar! 🥄"},
{n:"f",t:"Energia elétrica no dia a dia",q:"Qual destes funciona com energia elétrica?",a:["Bicicleta","Estilingue","Televisão","Pipa"],c:2,e:"A televisão precisa ser ligada na tomada: funciona com energia elétrica 📺. Bicicleta, estilingue e pipa usam a força do nosso corpo ou do vento."},
{n:"f",t:"Energia elétrica no dia a dia",q:"Qual usina gera eletricidade usando a força da água dos rios?",a:["Eólica","Solar","Nuclear","Hidrelétrica"],c:3,e:"A usina hidrelétrica usa a água dos rios, represada numa barragem, para girar turbinas e gerar eletricidade. 'Hidro' quer dizer água 💧."},
{n:"f",t:"Energia elétrica no dia a dia",q:"Qual usina usa a força do vento para gerar eletricidade?",a:["Usina eólica","Usina hidrelétrica","Usina nuclear","Usina termelétrica"],c:0,e:"A usina eólica tem grandes cata-ventos, os aerogeradores. O vento gira as pás, e esse movimento vira eletricidade 🌬️."},
{n:"f",t:"Energia elétrica no dia a dia",q:"Para a lâmpada de um circuito acender, o circuito precisa estar...",a:["Aberto","Fechado","Molhado","Sem pilha"],c:1,e:"Num circuito fechado, a corrente elétrica faz um caminho completo: sai da pilha, passa pelo fio e pela lâmpada e volta para a pilha. Se o caminho abrir, a lâmpada apaga 💡."},
{n:"f",t:"Energia elétrica no dia a dia",q:"Qual destas atitudes é PERIGOSA?",a:["Soltar pipa num campo aberto, longe dos fios","Desligar a TV quando ninguém está vendo","Colocar o dedo dentro da tomada","Secar as mãos antes de ligar o secador"],c:2,e:"Nunca coloque dedos nem objetos na tomada: pode dar um choque elétrico muito perigoso ⚡."},
{n:"f",t:"Energia elétrica no dia a dia",q:"Qual atitude ajuda a economizar energia elétrica?",a:["Deixar a TV ligada sem ninguém assistindo","Abrir a geladeira toda hora","Tomar banhos bem demorados","Apagar a luz ao sair do quarto"],c:3,e:"Luz acesa em quarto vazio é energia desperdiçada. Apagar a luz ao sair ajuda o planeta e a conta de luz 💡."},
{n:"f",t:"Energia elétrica no dia a dia",q:"O fio elétrico é de cobre por dentro e coberto de plástico por fora. Para que serve o plástico?",a:["Isolar e proteger contra choques","Fazer a eletricidade correr mais depressa","Deixar o fio mais pesado","Esquentar o fio"],c:0,e:"O cobre conduz a eletricidade, e o plástico é isolante: ele protege a gente de levar choque ao encostar no fio 🔌."},
{n:"f",t:"Energia elétrica no dia a dia",q:"Qual peça do circuito serve para ligar e desligar a lâmpada?",a:["O fio de cobre","O interruptor","A pilha","O soquete da lâmpada"],c:1,e:"O interruptor abre e fecha o circuito. Quando ele fecha, a corrente passa e a lâmpada acende; quando abre, ela apaga 🔘."},
{n:"m",t:"Formas de energia",q:"Um estilingue esticado, pronto para lançar uma pedrinha, guarda energia...",a:["Elástica, guardada no elástico","Elétrica, igual à da tomada","Química, igual à dos alimentos que comemos","Luminosa, igual à do Sol"],c:0,e:"Quando esticamos o elástico, ele guarda energia elástica (um tipo de energia potencial). Ao soltar, ela vira energia de movimento da pedrinha."},
{n:"m",t:"Formas de energia",q:"Qual destas fontes de energia é renovável?",a:["Carvão mineral","Bagaço de cana-de-açúcar","Gasolina","Gás natural tirado do subsolo"],c:1,e:"O bagaço de cana vem de plantas, que podem ser plantadas de novo a cada safra 🌱. Carvão mineral, gasolina e gás natural levam milhões de anos para se formar."},
{n:"m",t:"Formas de energia",q:"O que a gasolina, o gás de cozinha e a lenha têm em comum?",a:["São todos fontes renováveis","Produzem só energia sonora","Guardam energia química","São materiais transparentes"],c:2,e:"Todos eles guardam energia química, que é liberada como calor e luz quando queimam 🔥. Mas atenção: a lenha é renovável; a gasolina e o gás de cozinha, não."},
{n:"m",t:"Formas de energia",q:"Qual destas frases sobre a energia está CORRETA?",a:["A energia pode ser criada do nada","Quando uma pilha acaba, sua energia some do universo","Energia só existe em aparelhos elétricos","A energia se transforma de uma forma em outra"],c:3,e:"A energia não se cria nem se perde: ela se transforma. Quando a pilha descarrega, a energia dela virou luz, som, calor ou movimento nos aparelhos."},
{n:"m",t:"Formas de energia",q:"Por que o Sol é considerado a principal fonte de energia da Terra?",a:["Porque sua luz e seu calor sustentam a vida","Porque fica mais perto da Terra do que a Lua","Porque produz a energia das tomadas","Porque só brilha no verão"],c:0,e:"A luz e o calor do Sol aquecem o planeta, fazem as plantas crescerem e movem o ciclo da água e os ventos. Sem o Sol, não haveria vida na Terra ☀️."},
{n:"m",t:"Formas de energia",q:"Um carrinho parado no ponto mais alto da montanha-russa tem principalmente energia...",a:["Sonora, por causa dos gritos","De posição, por estar no alto","Luminosa, por causa das luzes do parque","Química, por causa do metal"],c:1,e:"Lá no alto, o carrinho guarda energia de posição (potencial). Quando ele desce, essa energia vira energia de movimento e ele dispara! 🎢"},
{n:"m",t:"Formas de energia",q:"Qual par mostra uma fonte renovável e uma NÃO renovável, nessa ordem?",a:["Petróleo e Sol","Sol e vento","Vento e petróleo","Carvão mineral e gás natural"],c:2,e:"O vento é renovável (sempre volta a soprar) e o petróleo não é (demora milhões de anos para se formar). Sol e vento são os dois renováveis; carvão e gás natural, os dois não renováveis."},
{n:"m",t:"Formas de energia",q:"O som de um tambor é produzido porque, ao ser batido, o couro do tambor...",a:["Esquenta","Brilha","Encolhe","Vibra"],c:3,e:"O som é energia sonora produzida por vibrações. O couro do tambor vibra e faz o ar vibrar até chegar aos nossos ouvidos 🥁."},
{n:"m",t:"Formas de energia",q:"Qual destas formas de obter energia NÃO depende de queimar combustível?",a:["Painel solar","Usina termelétrica a carvão","Motor de carro a gasolina","Fogão a lenha"],c:0,e:"O painel solar transforma a luz do Sol em eletricidade sem queimar nada. Carvão, gasolina e lenha precisam ser queimados para liberar energia."},
{n:"m",t:"Formas de energia",q:"O que significa dizer que uma fonte de energia é renovável?",a:["Que ela só pode ser usada uma única vez","Que a natureza a repõe sempre","Que ela é sempre mais barata","Que ela vem do petróleo"],c:1,e:"Fonte renovável é aquela que a natureza repõe sempre, como o Sol, o vento e a água dos rios. Por isso ela não corre o risco de acabar ♻️."},
{n:"m",t:"Transformações de energia",q:"Qual sequência mostra as transformações de energia numa lanterna ligada?",a:["Luminosa → química → elétrica","Elétrica → sonora → química","Química → elétrica → luminosa","Térmica → luminosa → sonora"],c:2,e:"A pilha guarda energia química, que vira energia elétrica nos fios e, na lâmpada, vira luz (energia luminosa) 🔦."},
{n:"m",t:"Transformações de energia",q:"Num carro andando, a energia química da gasolina se transforma principalmente em...",a:["Energia luminosa dos faróis apenas","Energia química de novo","Energia de posição","Energia de movimento (e calor)"],c:3,e:"O motor queima a gasolina: a energia química vira movimento das rodas. Uma parte vira calor (o motor esquenta) e som (o barulho do motor) 🚗."},
{n:"m",t:"Transformações de energia",q:"O ferro de passar roupa transforma energia elétrica principalmente em...",a:["Energia térmica","Energia sonora","Energia luminosa","Energia química"],c:0,e:"O ferro de passar esquenta: a energia elétrica vira calor, que tira o amassado da roupa 👕."},
{n:"m",t:"Transformações de energia",q:"Na usina eólica, qual energia é transformada em energia elétrica?",a:["A energia química do carvão queimado","A energia de movimento do vento","A energia luminosa da Lua","A energia térmica dos vulcões"],c:1,e:"O vento é ar em movimento. Ele gira as enormes pás dos aerogeradores, e esse movimento vira eletricidade 🌬️⚡."},
{n:"m",t:"Transformações de energia",q:"Que transformação de energia acontece quando uma vela está acesa?",a:["Elétrica em sonora e de movimento","Luminosa em química","Química em luminosa e térmica","Térmica em elétrica"],c:2,e:"A parafina da vela guarda energia química. Ao queimar, ela vira luz (energia luminosa) e calor (energia térmica) 🕯️."},
{n:"m",t:"Transformações de energia",q:"Uma bicicleta com dínamo acende o farol quando pedalamos. Ali, a energia de movimento vira...",a:["Energia química","Energia sonora","Energia de posição","Energia elétrica"],c:3,e:"O dínamo gira junto com a roda e transforma movimento em eletricidade, que acende o farol 🚲💡."},
{n:"m",t:"Transformações de energia",q:"Na fotossíntese, a planta transforma energia luminosa em...",a:["Energia química","Energia sonora","Energia elétrica","Energia de movimento"],c:0,e:"A planta usa a luz do Sol para fabricar seu alimento, e nele fica guardada energia química 🌿. É essa energia que passa para quem come a planta."},
{n:"m",t:"Transformações de energia",q:"Qual aparelho transforma energia elétrica principalmente em energia sonora?",a:["Torradeira","Caixa de som","Ferro de passar","Lâmpada"],c:1,e:"A caixa de som transforma eletricidade em som 🔊. A torradeira e o ferro transformam em calor, e a lâmpada, em luz."},
{n:"m",t:"Transformações de energia",q:"Ao chutar uma bola, qual energia do corpo se transforma no movimento da bola?",a:["Energia elétrica da tomada","Energia luminosa das lâmpadas do estádio","Energia química dos alimentos","Energia sonora do apito"],c:2,e:"Nossos músculos usam a energia química dos alimentos para se mover. No chute, parte dessa energia passa para a bola como energia de movimento ⚽."},
{n:"m",t:"Transformações de energia",q:"No aquecedor solar (canos e placas no telhado que esquentam a água do banho), a luz do Sol vira...",a:["Energia elétrica","Energia sonora","Energia química","Energia térmica"],c:3,e:"O aquecedor solar esquenta a água com a energia do Sol: a luz vira calor ☀️🚿. Não confunda com o painel solar, que produz eletricidade!"},
{n:"m",t:"Transformações de energia",q:"Qual transformação de energia acontece numa batedeira ligada?",a:["Elétrica em movimento","Química em luminosa","Movimento em elétrica","Luminosa em química"],c:0,e:"A batedeira usa energia elétrica para girar as pás: a eletricidade vira movimento (e também um pouco de som e calor)."},
{n:"m",t:"Transformações de energia",q:"Um fósforo aceso transforma energia química em...",a:["Energia elétrica e sonora","Energia luminosa e térmica","Energia de posição","Energia elétrica e química"],c:1,e:"Quando riscamos o fósforo, a energia química da cabeça dele vira luz e calor na chama 🔥."},
{n:"m",t:"Energia luminosa",q:"Os corpos que produzem a própria luz, como o Sol e uma lâmpada acesa, são chamados de...",a:["Corpos iluminados","Corpos opacos","Corpos luminosos","Corpos translúcidos"],c:2,e:"Corpos luminosos produzem luz própria: Sol, estrelas, fogo, lâmpada acesa. Corpos iluminados só refletem a luz que recebem, como a Lua e um livro."},
{n:"m",t:"Energia luminosa",q:"Qual destes é um corpo ILUMINADO, ou seja, que não produz luz e só reflete a luz que recebe?",a:["O Sol","Uma estrela","Uma lâmpada acesa","A Lua"],c:3,e:"A Lua não produz luz: ela é iluminada pelo Sol e reflete essa luz 🌙. O Sol, as estrelas e a lâmpada acesa são corpos luminosos."},
{n:"m",t:"Energia luminosa",q:"Como conseguimos enxergar um livro em cima da mesa?",a:["A luz que bate nele chega aos nossos olhos","Nossos olhos soltam luz","O livro produz sua própria luz","O livro faz um barulho que ouvimos"],c:0,e:"A luz da lâmpada ou do Sol bate no livro, é refletida e chega até os nossos olhos. É assim que enxergamos os objetos 👀."},
{n:"m",t:"Energia luminosa",q:"A luz do Sol leva cerca de 8 minutos para chegar à Terra, que fica a uns 150 milhões de quilômetros. Isso mostra que a luz...",a:["Anda devagar como um carro","Viaja muito rápido","Não atravessa o espaço vazio","Faz curvas pelo caminho"],c:1,e:"A luz é a coisa mais rápida que existe: percorre cerca de 300 mil quilômetros por segundo! Por isso atravessa uma distância enorme em só 8 minutos ⚡."},
{n:"m",t:"Energia luminosa",q:"Num dia de sol, a sombra de uma árvore fica do lado...",a:["Virado para o Sol","Para onde o vento sopra","Oposto ao Sol","Em cima dos galhos"],c:2,e:"A árvore bloqueia a luz que vem do Sol, então a sombra aparece do outro lado, oposto ao Sol 🌳."},
{n:"m",t:"Energia luminosa",q:"Ao colocar a mão na frente de uma lanterna, aparece uma sombra na parede porque a mão...",a:["É transparente","Produz luz própria","Reflete toda a luz como um espelho","É opaca e bloqueia a luz"],c:3,e:"A mão é opaca: não deixa a luz passar. Atrás dela a luz não chega à parede, e ali se forma a sombra ✋."},
{n:"m",t:"Energia luminosa",q:"Qual destes materiais é translúcido?",a:["Papel vegetal","Vidro transparente da janela","Tábua de madeira","Placa de ferro"],c:0,e:"O papel vegetal deixa passar um pouco de luz, mas não dá para ver nitidamente através dele: é translúcido. Madeira e ferro são opacos; o vidro da janela é transparente."},
{n:"m",t:"Energia luminosa",q:"Ao passar por um prisma de vidro, a luz branca...",a:["Some completamente","Se separa nas cores do arco-íris","Vira luz preta","Vira fogo e esquenta o vidro inteiro"],c:1,e:"A luz branca é a mistura de várias cores. O prisma separa essas cores, como as gotas de chuva fazem no arco-íris 🌈."},
{n:"m",t:"Energia luminosa",q:"O espelho retrovisor permite ao motorista ver o que está atrás do carro porque...",a:["O espelho produz luz","O espelho absorve toda a luz","O espelho reflete a luz","O espelho é translúcido"],c:2,e:"O espelho é liso e polido e reflete a luz que vem dos carros de trás até os olhos do motorista. Isso é a reflexão da luz 🚗🪞."},
{n:"m",t:"Energia luminosa",q:"Por que não conseguimos ver uma lanterna acesa olhando por dentro de um cano dobrado?",a:["Porque o cano dobrado fabrica escuridão","Porque a luz fica presa no ar","Porque a lanterna desliga sozinha","Porque a luz anda em linha reta"],c:3,e:"A luz anda em linha reta e não consegue fazer a curva do cano. Com um cano reto, a gente veria a luz da lanterna 🔦."},
{n:"m",t:"Energia térmica e calor",q:"Qual frase usa a palavra calor do jeito correto da ciência?",a:["Calor é energia térmica passando do mais quente para o mais frio","Calor e temperatura são exatamente a mesma coisa, só mudam de nome","O frio é uma energia que passa do gelo para a nossa mão","Calor é uma coisa que o casaco fabrica e guarda dentro dele"],c:0,e:"Na ciência, calor é a energia térmica que passa de um corpo mais quente para um mais frio. Temperatura é outra coisa: indica o quanto algo está quente ou frio 🌡️."},
{n:"m",t:"Energia térmica e calor",q:"Misturando um copo de água quente com um copo igual de água gelada, a água fica...",a:["Fervendo","Morna","Congelada","Mais quente que a água quente"],c:1,e:"A água quente passa calor para a gelada até as duas ficarem com a mesma temperatura, que fica no meio: morna 💧."},
{n:"m",t:"Energia térmica e calor",q:"Quando dois objetos encostados chegam à mesma temperatura e param de trocar calor, dizemos que estão em...",a:["Ebulição","Condensação","Equilíbrio térmico","Dilatação"],c:2,e:"Equilíbrio térmico é quando os corpos ficam com a mesma temperatura. Aí o calor para de passar de um para o outro ⚖️."},
{n:"m",t:"Energia térmica e calor",q:"Um termômetro de rua marcou 12 °C pela manhã e 30 °C à tarde. O que aconteceu com a temperatura?",a:["Diminuiu 18 °C","Aumentou 42 °C","Ficou igual","Aumentou 18 °C"],c:3,e:"De 12 °C para 30 °C a temperatura subiu: 30 − 12 = 18. Então ela aumentou 18 °C 🌡️."},
{n:"m",t:"Energia térmica e calor",q:"O termômetro de uma criança marcou 39 °C. Isso indica que ela provavelmente está...",a:["Com febre","Com a temperatura normal","Muito gelada, quase congelando","Com o corpo a 0 °C"],c:0,e:"A temperatura normal do corpo fica por volta de 36 a 37 °C. Com 39 °C, a criança está com febre e precisa dos cuidados de um adulto 🤒."},
{n:"m",t:"Energia térmica e calor",q:"Um sorvete deixado na mesa derrete porque...",a:["Solta o frio dele para o ar","Recebe calor do ambiente","Recebe frio da mesa","O açúcar dele ferve"],c:1,e:"O ambiente está mais quente que o sorvete, então o calor passa do ar e da mesa para o sorvete, que derrete 🍦."},
{n:"m",t:"Energia térmica e calor",q:"Uma lata de refrigerante gelada é deixada na mesa por várias horas. No final, ela estará...",a:["Cada vez mais gelada","Mais quente que o ambiente","Na temperatura do ambiente","Congelada"],c:2,e:"A lata recebe calor do ar até ficar com a mesma temperatura do ambiente. Aí as trocas de calor param: é o equilíbrio térmico."},
{n:"m",t:"Energia térmica e calor",q:"Qual termômetro é usado para medir a temperatura do corpo de uma pessoa?",a:["Termômetro de forno","Barômetro","Velocímetro","Termômetro clínico"],c:3,e:"O termômetro clínico mede a temperatura do corpo, por exemplo na axila 🌡️. Barômetro mede a pressão do ar, e velocímetro, a velocidade."},
{n:"m",t:"Energia térmica e calor",q:"Na escala Celsius, a marca de 0 °C é a temperatura em que...",a:["A água congela","A água ferve","O corpo humano fica normal","O ferro derrete"],c:0,e:"A escala Celsius foi feita usando a água: 0 °C é onde a água congela e 100 °C é onde ela ferve (ao nível do mar)."},
{n:"m",t:"Energia térmica e calor",q:"Por que as mãos aquecem quando seguramos uma xícara de chocolate quente?",a:["Porque as mãos passam calor para a xícara","Porque o calor passa da xícara para as mãos","Porque o frio das mãos escapa para dentro da xícara","Porque a xícara produz frio"],c:1,e:"A xícara está mais quente que as mãos, então o calor passa dela para nós. O calor sempre vai do mais quente para o mais frio ☕."},
{n:"m",t:"Efeitos do calor",q:"Aparecem gotinhas de água do lado de fora de um copo com água gelada. De onde elas vêm?",a:["Da água de dentro do copo","Do gelo que derreteu por fora","Do vapor do ar, que condensa no copo frio","Do suor das nossas mãos"],c:2,e:"O ar tem vapor de água invisível. Quando ele encosta no copo gelado, perde calor e condensa, virando gotinhas. A água de dentro não atravessa o vidro! 🥤"},
{n:"m",t:"Efeitos do calor",q:"Qual destes é um exemplo de evaporação, e NÃO de ebulição?",a:["A água borbulhando na chaleira","A água fervendo para o macarrão","A sopa borbulhando na panela","A poça d'água secando ao sol"],c:3,e:"A poça seca devagar, sem ferver: é evaporação. Quando a água borbulha e ferve, como na chaleira, é ebulição ☀️."},
{n:"m",t:"Efeitos do calor",q:"Para abrir um pote de vidro com tampa de metal muito apertada, uma dica é passar a tampa na água quente. Isso funciona porque o metal...",a:["Dilata com o calor e afrouxa","Encolhe com o calor","Derrete um pouquinho com a água quente","Fica mais grudento"],c:0,e:"O metal da tampa dilata mais que o vidro quando é aquecido. A tampa fica um pouquinho maior e solta com mais facilidade 🫙."},
{n:"m",t:"Efeitos do calor",q:"Um balão de festa cheio de ar é deixado no sol forte. O que tende a acontecer?",a:["Murchar bastante","Inchar um pouco","Congelar por dentro","Ficar mais pesado"],c:1,e:"O calor faz o ar dentro do balão dilatar e ocupar mais espaço, então o balão incha. Se esquentar demais, pode até estourar 🎈."},
{n:"m",t:"Efeitos do calor",q:"Nas calçadas e pontes existem pequenos vãos chamados juntas de dilatação. Para que eles servem?",a:["Deixar a água da chuva escorrer pelo meio","Enfeitar a calçada","Dar espaço para o material dilatar","Deixar a ponte mais leve"],c:2,e:"No calor, o concreto dilata. As juntas dão espaço para essa dilatação e evitam que a calçada ou a ponte rache 🌉."},
{n:"m",t:"Efeitos do calor",q:"Em qual situação a água está passando do estado líquido para o sólido?",a:["Fervendo a água do chá","Secando a roupa no varal","Derretendo o gelo dentro do copo de suco","Fazendo picolé no congelador"],c:3,e:"No congelador, o suco do picolé perde calor e vira sólido: é a solidificação 🍭. Derreter o gelo é o contrário: fusão."},
{n:"m",t:"Efeitos do calor",q:"Um termômetro de líquido colorido funciona porque, quando a temperatura sobe, o líquido...",a:["Dilata e sobe no tubinho","Contrai e sobe","Evapora e some","Muda de cor conforme a temperatura"],c:0,e:"Com o calor, o líquido do termômetro dilata e ocupa mais espaço, subindo pelo tubinho fino. Quando esfria, ele contrai e desce 🌡️."},
{n:"m",t:"Efeitos do calor",q:"O que acontece com a água quando ela evapora?",a:["Passa do estado gasoso para o líquido","Passa do estado líquido para o gasoso","Passa do estado sólido para o líquido","Passa do estado líquido para o sólido"],c:1,e:"Na evaporação, a água líquida vira vapor (gás), que se espalha no ar. É o que acontece com a roupa secando no varal 👕."},
{n:"m",t:"Efeitos do calor",q:"Por que os fios entre os postes ficam mais caídos (barrigudos) nos dias muito quentes?",a:["Porque muitos passarinhos pousam neles","Porque o metal encolhe com o calor","Porque o calor os dilata","Porque a chuva deixa os fios pesados"],c:2,e:"Os fios são de metal. No calor, eles dilatam e ficam um pouquinho mais compridos, por isso aparecem mais caídos entre os postes."},
{n:"m",t:"Efeitos do calor",q:"O que acontece com a água das poças que secam num dia de sol depois da chuva?",a:["Congela no chão quente","Some e deixa de existir de verdade","Se transforma em terra","Vira vapor e vai para o ar"],c:3,e:"O calor do Sol faz a água das poças evaporar: ela vira vapor e vai para o ar. Lá em cima, esse vapor pode formar nuvens ☁️."},
{n:"m",t:"Condutores e isolantes de calor",q:"Para mexer uma panela no fogo por muito tempo, qual colher é a mais adequada?",a:["Colher de madeira","Colher de alumínio","Colher de ferro","Colher de cobre"],c:0,e:"A madeira é isolante: o calor da panela demora a chegar até a mão. Colheres de metal esquentam e podem queimar 🥄."},
{n:"m",t:"Condutores e isolantes de calor",q:"Por que as aves arrepiam as penas nos dias frios?",a:["Para fabricar calor","Para prender ar, que é isolante","Para ficarem mais bonitas","Para voarem mais rápido"],c:1,e:"Entre as penas arrepiadas fica muito ar preso. O ar parado é isolante e dificulta a saída do calor do corpo da ave 🐦."},
{n:"m",t:"Condutores e isolantes de calor",q:"O iglu é uma casa feita de blocos de neve compactada. Por que dentro dele fica menos frio do que fora?",a:["O gelo conduz o calor do Sol para dentro","A neve produz calor","A neve isola e segura o calor de dentro","O iglu tem aquecedor elétrico"],c:2,e:"A neve compactada tem ar preso e é isolante. Ela dificulta a saída do calor das pessoas lá dentro e protege do vento gelado ❄️."},
{n:"m",t:"Condutores e isolantes de calor",q:"A garrafa térmica tem parede dupla, quase sem ar entre as paredes. Para que serve isso?",a:["Deixar a garrafa mais pesada","Fazer o café ferver dentro dela","Gelar o café quente","Dificultar a passagem do calor"],c:3,e:"Sem ar entre as paredes, o calor tem muita dificuldade para passar. Assim, o café continua quente por horas ☕."},
{n:"m",t:"Condutores e isolantes de calor",q:"Um sorveteiro guarda os picolés numa caixa de isopor. O que o isopor faz?",a:["Dificulta a entrada de calor","Fabrica frio para os picolés","Conduz muito bem o calor para dentro","Deixa o frio entrar"],c:0,e:"O isopor é isolante: dificulta que o calor do ambiente entre na caixa. Assim, os picolés demoram mais para derreter 🍦."},
{n:"m",t:"Condutores e isolantes de calor",q:"Por que um cobertor nos mantém aquecidos à noite?",a:["Porque guardou o calor do Sol","Porque segura o calor do corpo","Porque produz calor sozinho","Porque esfria o ar do quarto"],c:1,e:"O cobertor não produz calor: ele é isolante e dificulta a saída do calor que o nosso corpo produz. Por isso ficamos quentinhos 🛏️."},
{n:"m",t:"Condutores e isolantes de calor",q:"Qual par mostra um bom condutor e um bom isolante de calor, nessa ordem?",a:["Isopor e cobre","Lã e madeira","Cobre e isopor","Alumínio e ferro"],c:2,e:"O cobre, como todo metal, conduz bem o calor, e o isopor é isolante. Lã e madeira são os dois isolantes; alumínio e ferro, os dois condutores."},
{n:"m",t:"Condutores e isolantes de calor",q:"Por que panelas de cobre ou de alumínio cozinham os alimentos mais depressa?",a:["Porque são isolantes de calor","Porque são mais leves","Porque refletem a luz","Porque conduzem bem o calor"],c:3,e:"Cobre e alumínio são ótimos condutores: levam o calor do fogo até o alimento bem rápido 🍳."},
{n:"m",t:"Condutores e isolantes de calor",q:"O pegador de panela de tecido grosso protege a mão porque o tecido...",a:["É isolante de calor","É bom condutor de calor","Esfria a panela","Produz frio"],c:0,e:"O tecido grosso é isolante: o calor da panela passa para a mão muito devagar, e assim não nos queimamos."},
{n:"m",t:"Condutores e isolantes de calor",q:"Para um gelo durar mais tempo num passeio, é melhor embrulhá-lo em...",a:["Um prato de metal, no sol","Jornal ou pano grosso","Nada: deixar ao ar livre, no sol","Uma panela de metal quente"],c:1,e:"Jornal e pano grosso são isolantes: dificultam que o calor do ambiente chegue ao gelo. Assim ele derrete mais devagar 🧊."},
{n:"m",t:"Energia elétrica no dia a dia",q:"No Brasil, a maior parte da energia elétrica é produzida em qual tipo de usina?",a:["Usinas nucleares","Usinas de queima de lenha","Usinas hidrelétricas","Usinas a carvão"],c:2,e:"O Brasil tem muitos rios grandes, por isso a maior parte da nossa eletricidade vem de hidrelétricas, como Itaipu 💧⚡."},
{n:"m",t:"Energia elétrica no dia a dia",q:"O que fazem as linhas de transmissão, aquelas torres altas cheias de fios?",a:["Produzem eletricidade com o vento","Guardam eletricidade como pilhas","Medem a temperatura do ar","Levam a eletricidade das usinas às cidades"],c:3,e:"As usinas costumam ficar longe das cidades. As linhas de transmissão levam a eletricidade por longas distâncias até chegar às casas 🗼."},
{n:"m",t:"Energia elétrica no dia a dia",q:"Qual destes materiais é um bom condutor de eletricidade?",a:["Cobre","Borracha","Plástico","Madeira seca"],c:0,e:"O cobre é um metal e conduz muito bem a eletricidade, por isso é usado dentro dos fios. Borracha, plástico e madeira seca são isolantes."},
{n:"m",t:"Energia elétrica no dia a dia",q:"Qual destes materiais é um isolante elétrico, usado para proteger contra choques?",a:["Cobre","Borracha","Alumínio","Ferro"],c:1,e:"A borracha não deixa a eletricidade passar com facilidade: é isolante. Cobre, alumínio e ferro são metais e conduzem eletricidade."},
{n:"m",t:"Energia elétrica no dia a dia",q:"Num circuito com pilha, fios e lâmpada, um dos fios se solta. O que acontece?",a:["A lâmpada passa a brilhar mais forte","A pilha se recarrega sozinha","A lâmpada apaga","Nada muda"],c:2,e:"Com o fio solto, o caminho da corrente elétrica fica interrompido: o circuito está aberto e a lâmpada apaga."},
{n:"m",t:"Energia elétrica no dia a dia",q:"Por que é perigoso usar o secador de cabelo com as mãos molhadas ou perto da banheira cheia?",a:["Porque a água o deixa mais forte","Porque o secador esfria a água","Porque a água apaga o secador","Porque a água conduz eletricidade"],c:3,e:"A água comum, como a da torneira, conduz eletricidade. Mãos molhadas ou aparelho perto da água podem causar um choque grave ⚠️."},
{n:"m",t:"Energia elétrica no dia a dia",q:"Por que não devemos soltar pipa perto da rede elétrica?",a:["A linha pode tocar os fios e dar choque","Os fios puxam a pipa como um ímã gigante","A pipa voa mais baixo perto dos fios","A pipa perde a cor"],c:0,e:"A linha pode enroscar nos fios e causar choque, queimaduras e falta de luz. Solte pipa em campos abertos, longe da rede elétrica 🪁."},
{n:"m",t:"Energia elétrica no dia a dia",q:"Qual destes aparelhos costuma gastar MUITA energia elétrica numa casa?",a:["Carregador de celular","Chuveiro elétrico","Lâmpada de LED","Rádio pequeno"],c:1,e:"O chuveiro elétrico usa muita energia para esquentar a água. Por isso banhos curtos ajudam bastante a economizar 🚿."},
{n:"d",t:"Formas de energia",q:"De onde veio, lá no começo, a energia guardada na gasolina?",a:["Do Sol, captado por seres vivos há milhões de anos","Da eletricidade dos postos","Do motor do carro","Do ar que entra no tanque"],c:0,e:"O petróleo se formou de restos de seres vivos muito antigos, que tinham energia vinda do Sol (pela fotossíntese). A gasolina guarda energia do Sol de milhões de anos atrás!"},
{n:"d",t:"Formas de energia",q:"Uma pilha nova acendeu uma lanterna até ficar 'gasta'. O que aconteceu com a energia química que ela tinha?",a:["Sumiu completamente","Virou outras formas, como luz e calor","Continua toda dentro da pilha","Voltou para a fábrica"],c:1,e:"A energia não some: a energia química da pilha virou elétrica e, na lâmpada, virou luz e calor, que se espalharam pelo ambiente 🔦."},
{n:"d",t:"Formas de energia",q:"O vento existe porque o Sol aquece o ar de forma desigual. Então, a energia de uma usina eólica vem, no fundo, de onde?",a:["Do petróleo","Do centro da Terra","Do Sol","Da força da Lua"],c:2,e:"Sem o Sol aquecendo o ar, não haveria vento. Então a energia do vento é, no fundo, energia do Sol ☀️🌬️."},
{n:"d",t:"Formas de energia",q:"Em qual situação a energia de posição está se transformando em energia de movimento?",a:["Uma lâmpada acendendo","Um rádio tocando","Uma pilha guardada na gaveta","Uma maçã caindo do galho"],c:3,e:"A maçã no galho está no alto e guarda energia de posição. Ao cair, essa energia vira energia de movimento 🍎."},
{n:"d",t:"Formas de energia",q:"Um menino diz: 'O carrinho de corda parou, então a energia dele sumiu'. Qual é a explicação correta?",a:["Ela virou calor e som, por causa do atrito","Ela voltou sozinha para a corda","Ela sumiu mesmo","Ela virou mais corda"],c:0,e:"Energia não some! Enquanto o carrinho andava, o atrito com o chão e o barulho do motorzinho transformaram a energia em calor e som."},
{n:"d",t:"Formas de energia",q:"Por que é importante usar mais fontes renováveis, como o Sol e o vento?",a:["São sempre gratuitas para todos","Não se esgotam e poluem menos","Produzem energia química","Funcionam só à noite"],c:1,e:"Fontes renováveis não acabam e, em geral, poluem bem menos do que queimar petróleo e carvão. É bom para o planeta 🌎."},
{n:"d",t:"Formas de energia",q:"Qual destas fontes é renovável E não precisa ser queimada para gerar energia?",a:["Lenha","Carvão mineral","Energia solar","Gás natural"],c:2,e:"A lenha até é renovável, mas precisa ser queimada. Carvão mineral e gás natural não são renováveis. A energia solar é renovável e não queima nada ☀️."},
{n:"d",t:"Formas de energia",q:"A água no alto de uma represa guarda energia de posição. Quando ela desce pelos tubos até a turbina, essa energia se transforma primeiro em...",a:["Energia química","Energia luminosa","Energia sonora","Energia de movimento"],c:3,e:"Ao descer, a água ganha velocidade: a energia de posição vira energia de movimento. Depois, esse movimento gira a turbina e vira eletricidade."},
{n:"d",t:"Formas de energia",q:"Qual alternativa relaciona corretamente o exemplo com a forma de energia?",a:["Pão: energia química","Violão tocando: energia luminosa","Lâmpada acesa: energia sonora","Fogueira: energia elétrica"],c:0,e:"O pão guarda energia química. O violão produz energia sonora, a lâmpada produz luz e a fogueira produz calor e luz."},
{n:"d",t:"Formas de energia",q:"O petróleo vem de restos de seres vivos. Mesmo assim, por que ele é uma fonte NÃO renovável?",a:["Porque não se forma mais de jeito nenhum hoje em dia","Porque demora milhões de anos para se formar","Porque só existe em pouquíssimos países do mundo","Porque a gasolina não guarda energia química"],c:1,e:"O petróleo leva milhões de anos para se formar, e nós o gastamos muito mais rápido. Para a vida humana, ele não se renova: um dia pode acabar ⛽."},
{n:"d",t:"Transformações de energia",q:"Qual sequência mostra corretamente o caminho da energia até um menino conseguir correr?",a:["Corpo → alimento → planta → Sol","Alimento → Sol → planta → corpo","Sol → planta → alimento → corpo","Planta → corpo → Sol → alimento"],c:2,e:"A planta capta a luz do Sol e guarda energia química. Comemos alimentos que vêm das plantas (ou de animais que comeram plantas), e o corpo usa essa energia para se mover 🏃."},
{n:"d",t:"Transformações de energia",q:"Gustavo comeu arroz e feijão no almoço e depois jogou futebol. De onde veio, lá no começo, a energia que ele usou para correr?",a:["Da água gelada que ele bebeu","Do ar que respirou","Do gramado do campo","Do Sol, captado pelas plantas"],c:3,e:"Arroz e feijão vêm de plantas, que guardaram a energia da luz do Sol pela fotossíntese. Ao comer, Gustavo recebeu essa energia e a usou para correr ⚽☀️."},
{n:"d",t:"Transformações de energia",q:"Qual é a sequência correta do que acontece numa usina hidrelétrica?",a:["Água cai → turbina gira → gerador produz eletricidade","Turbina gira → água cai → gerador produz calor","Gerador produz eletricidade → água cai → turbina para","Água evapora → turbina congela → gerador produz luz"],c:0,e:"A água desce com força e gira a turbina. A turbina está ligada ao gerador, que transforma esse movimento em energia elétrica ⚡."},
{n:"d",t:"Transformações de energia",q:"A eletricidade de uma hidrelétrica também depende do Sol. Por quê?",a:["A usina tem painéis solares","O Sol move o ciclo da água que enche os rios","A água só corre de dia","O Sol empurra a água"],c:1,e:"O Sol evapora a água de mares, rios e plantas. Esse vapor forma nuvens e cai como chuva, enchendo rios e represas. Sem Sol, não haveria chuva para a usina 🌧️."},
{n:"d",t:"Transformações de energia",q:"Uma lâmpada incandescente (das antigas) esquenta muito; uma de LED quase não esquenta. O que isso indica?",a:["A lâmpada antiga não usa eletricidade","O LED produz energia do nada","O LED desperdiça menos energia em calor","As duas gastam a mesma energia"],c:2,e:"Na lâmpada antiga, boa parte da energia elétrica vira calor, e não luz. O LED transforma mais energia em luz e desperdiça menos em calor, por isso é mais econômico 💡."},
{n:"d",t:"Transformações de energia",q:"Qual alternativa mostra um aparelho e sua transformação de energia PRINCIPAL corretamente?",a:["Ventilador: elétrica → luminosa","Rádio: elétrica → química","Painel solar: elétrica → luminosa","Torradeira: elétrica → térmica"],c:3,e:"A torradeira esquenta o pão: elétrica vira térmica 🍞. O ventilador transforma em movimento, o rádio em som, e o painel solar faz o caminho contrário: luz vira eletricidade."},
{n:"d",t:"Transformações de energia",q:"O painel solar e o aquecedor solar usam a luz do Sol. Qual é a diferença entre eles?",a:["O painel produz eletricidade; o aquecedor esquenta a água","O painel esquenta a água; o aquecedor produz eletricidade","Os dois produzem eletricidade","Os dois só servem para esquentar a água"],c:0,e:"Painel solar (fotovoltaico): luz vira eletricidade. Aquecedor solar: luz vira calor para esquentar a água do banho. Os dois aproveitam o Sol de jeitos diferentes ☀️."},
{n:"d",t:"Transformações de energia",q:"Por que nosso corpo fica quente mesmo num dia frio, e esquenta ainda mais quando corremos?",a:["As roupas fabricam calor","O corpo transforma a energia dos alimentos em calor","O ar frio vira calor no corpo","O coração tem fogo dentro"],c:1,e:"O corpo transforma a energia química dos alimentos em movimento e em calor. Quando corremos, essa transformação aumenta e esquentamos mais 🏃🔥."},
{n:"d",t:"Transformações de energia",q:"Num celular, a bateria faz a tela acender e o alto-falante tocar. Qual sequência de transformações acontece?",a:["Luminosa → química → elétrica","Sonora → elétrica → química","Química → elétrica → luz e som","Elétrica → química → movimento e calor"],c:2,e:"A bateria guarda energia química, que vira elétrica. Na tela, a eletricidade vira luz; no alto-falante, vira som 📱."},
{n:"d",t:"Transformações de energia",q:"Um carrinho de brinquedo a pilha sobe uma rampa e para lá no alto. Qual sequência de transformações aconteceu?",a:["Posição → movimento → elétrica → química","Elétrica → química → posição → movimento","Movimento → posição → química → elétrica","Química → elétrica → movimento → posição"],c:3,e:"A pilha (química) gera eletricidade, que faz o motor girar (movimento). Ao subir a rampa, o carrinho ganha energia de posição por estar no alto 🚗."},
{n:"d",t:"Transformações de energia",q:"Na usina termelétrica, carvão ou gás é queimado para ferver água, e o vapor gira a turbina. Qual sequência está certa?",a:["Química → térmica → movimento → elétrica","Elétrica → movimento → térmica → química","Térmica → química → elétrica → movimento","Movimento → elétrica → química → térmica"],c:0,e:"O combustível (química) queima e gera calor (térmica), que ferve a água. O vapor gira a turbina (movimento), e o gerador produz eletricidade (elétrica) 🏭."},
{n:"d",t:"Transformações de energia",q:"Por que o motor de um liquidificador fica um pouco quente depois de funcionar muito tempo?",a:["O motor puxou o calor da cozinha","Parte da energia elétrica virou calor","A fruta esquentou o motor","Sobrou energia criada a mais"],c:1,e:"Nenhum aparelho transforma toda a energia só naquilo que queremos. No liquidificador, a maior parte vira movimento, mas uma parte vira som e calor."},
{n:"d",t:"Energia luminosa",q:"Numa tempestade, vemos o relâmpago e só alguns segundos depois ouvimos o trovão. Por quê?",a:["O trovão acontece bem depois do raio","O som é mais rápido que a luz","A luz viaja muito mais rápido que o som","Os olhos são mais rápidos que os ouvidos"],c:2,e:"O relâmpago e o trovão acontecem juntos, mas a luz é muitíssimo mais rápida que o som. Por isso a luz chega primeiro e o barulho vem depois ⚡🔊."},
{n:"d",t:"Energia luminosa",q:"Gustavo aproxima um boneco da lanterna, sem mexer na parede. O que acontece com a sombra do boneco na parede?",a:["Fica menor","Some","Fica colorida","Fica maior"],c:3,e:"Quanto mais perto da lanterna, mais luz o boneco bloqueia, e a sombra na parede fica maior. Afastando o boneco da lanterna, a sombra diminui."},
{n:"d",t:"Energia luminosa",q:"Ao meio-dia, com o Sol bem alto no céu, como fica a nossa sombra?",a:["Bem curta","Bem comprida","Do mesmo tamanho da sombra do fim da tarde","Fica colorida"],c:0,e:"Com o Sol lá no alto, a luz vem de cima e a sombra fica curtinha, perto dos pés. De manhã cedo e no fim da tarde, com o Sol baixo, as sombras ficam compridas."},
{n:"d",t:"Energia luminosa",q:"Num dia de sol, por que uma camiseta preta esquenta mais do que uma branca?",a:["O branco fabrica frio","O preto absorve mais luz, que vira calor","O preto reflete toda a luz","O preto é mais pesado"],c:1,e:"Tecidos escuros absorvem mais a luz do Sol, e essa energia luminosa vira calor. O branco reflete mais a luz, por isso esquenta menos ☀️👕."},
{n:"d",t:"Energia luminosa",q:"Por que enxergamos uma maçã com a cor vermelha?",a:["Ela produz sua própria luz vermelha","Ela absorve toda a luz vermelha","Ela reflete mais a luz vermelha","Ela é transparente para o vermelho"],c:2,e:"A luz branca tem todas as cores. A maçã absorve a maior parte delas e reflete principalmente o vermelho, que chega aos nossos olhos 🍎."},
{n:"d",t:"Energia luminosa",q:"Um periscópio permite enxergar por cima de um muro sem subir nele. Como ele funciona?",a:["Lentes que entortam a luz","Lâmpadas dentro do tubo","Vidros foscos","Dois espelhos que refletem a luz"],c:3,e:"No periscópio, a luz entra por cima, bate num espelho, desce pelo tubo e bate em outro espelho até chegar ao olho. É a reflexão da luz trabalhando 🪞."},
{n:"d",t:"Energia luminosa",q:"Qual situação mostra que a luz se propaga em linha reta?",a:["A sombra tem o formato do objeto","O vidro fosco deixando a imagem embaçada","O arco-íris depois da chuva","A Lua brilhando à noite"],c:0,e:"Como a luz anda em linha reta, o objeto bloqueia os raios exatamente no seu contorno. Por isso a sombra tem o formato do objeto 🖐️."},
{n:"d",t:"Energia luminosa",q:"Para ver um arco-íris, onde deve estar o Sol em relação a quem observa?",a:["Na frente da pessoa, atrás da chuva","Atrás da pessoa, com chuva à frente","Exatamente em cima da cabeça","Escondido atrás de nuvens grossas"],c:1,e:"O arco-íris aparece no lado oposto ao Sol. A pessoa fica de costas para o Sol, olhando para a chuva, e as gotinhas separam as cores da luz 🌈."},
{n:"d",t:"Energia luminosa",q:"Uma janela de vidro comum, uma cortina fina e uma parede de tijolos são, nessa ordem:",a:["Opaca, translúcida e transparente","Translúcida, transparente e opaca","Transparente, translúcida e opaca","Transparente, opaca e translúcida"],c:2,e:"O vidro comum deixa ver tudo (transparente), a cortina fina deixa passar só parte da luz (translúcida) e a parede bloqueia toda a luz (opaca)."},
{n:"d",t:"Energia luminosa",q:"Num quarto totalmente escuro, sem nenhuma luz, conseguimos ver nossa imagem num espelho?",a:["Sim, os olhos lançam luz","Sim, o espelho brilha sozinho","Só se o espelho for grande","Não, pois não há luz para refletir"],c:3,e:"O espelho não tem luz própria: ele só reflete a luz que recebe. Sem nenhuma luz no quarto, não há nada para refletir até os nossos olhos."},
{n:"d",t:"Energia térmica e calor",q:"Uma panela grande e uma xícara têm água a 80 °C. Qual afirmação está correta?",a:["Mesma temperatura, mas a panela tem mais energia térmica","A xícara tem mais energia térmica","A panela está mais quente","A xícara está mais quente"],c:0,e:"O termômetro marca 80 °C nas duas, então a temperatura é igual. Mas a panela tem muito mais água, por isso guarda mais energia térmica e demora mais para esfriar."},
{n:"d",t:"Energia térmica e calor",q:"Gustavo deixou a mão um tempo na água gelada e depois a colocou numa bacia de água morna. A água morna pareceu quente! O que isso mostra?",a:["A água morna esquentou sozinha","O tato engana; o termômetro é mais confiável","A mão passou frio para a água","A água morna estava fervendo"],c:1,e:"Nossa sensação de quente e frio depende de como a pele estava antes, então pode enganar. Para saber a temperatura de verdade, usamos o termômetro 🌡️."},
{n:"d",t:"Energia térmica e calor",q:"Pela manhã, o termômetro marcava 14 °C. Até o meio-dia, a temperatura subiu 9 °C e, à noite, caiu 6 °C em relação ao meio-dia. Qual era a temperatura à noite?",a:["23 °C","29 °C","17 °C","11 °C"],c:2,e:"14 + 9 = 23 °C ao meio-dia. Depois caiu 6: 23 − 6 = 17 °C à noite 🌙."},
{n:"d",t:"Energia térmica e calor",q:"Um copo de água gelada e outro de água quente ficam horas numa mesa. No final, os dois estarão na temperatura do ambiente. Por quê?",a:["Cada um produz o próprio frio ou calor","O copo esconde a temperatura","A água perde peso","Os dois trocam calor com o ar até se igualar"],c:3,e:"A água gelada recebe calor do ar e a quente perde calor para o ar, até tudo ficar com a mesma temperatura: é o equilíbrio térmico ⚖️."},
{n:"d",t:"Energia térmica e calor",q:"Qual destas frases está CORRETA?",a:["O gelo esfria o suco porque recebe calor do suco","O gelo esfria o suco porque solta muito frio dentro dele","O suco esquenta o gelo porque recebe calor dele","O frio passa do gelo para o suco"],c:0,e:"O frio não é uma coisa que passa! O suco, mais quente, perde calor para o gelo. Por isso o suco esfria e o gelo derrete 🧃."},
{n:"d",t:"Energia térmica e calor",q:"Uma pessoa com febre coloca uma toalha molhada e fria na testa. O que acontece?",a:["O frio da toalha entra na testa","O calor passa da testa para a toalha","A toalha produz frio","A toalha fica mais gelada"],c:1,e:"A testa está mais quente que a toalha, então o calor sai da testa e vai para a toalha. Assim a testa esfria e a toalha esquenta."},
{n:"d",t:"Energia térmica e calor",q:"Uma lata gelada (5 °C) e outra que estava no sol (40 °C) são deixadas numa sala a 25 °C. Depois de muitas horas...",a:["A gelada continua a 5 °C","A do sol continua a 40 °C","As duas ficam a cerca de 25 °C","As duas ficam a 0 °C"],c:2,e:"A lata gelada recebe calor do ar e a lata quente perde calor para o ar. As duas acabam na temperatura da sala, 25 °C: equilíbrio térmico."},
{n:"d",t:"Energia térmica e calor",q:"Alguém diz: 'Hoje está fazendo muito calor'. Do jeito da ciência, o mais correto seria dizer que...",a:["O calor está parado no ar","O ar está cheio de frio","O termômetro produz calor","A temperatura está alta"],c:3,e:"No dia a dia falamos 'está calor', mas na ciência o certo é dizer que a temperatura está alta. Calor é a energia que passa de um corpo mais quente para um mais frio."},
{n:"d",t:"Energia térmica e calor",q:"Em qual destas situações o calor está passando do ambiente para um objeto?",a:["Um picolé derretendo na praia","Um café esfriando na xícara","Uma panela quente esfriando no balcão","Uma mão esfriando ao segurar gelo"],c:0,e:"O ar da praia está mais quente que o picolé, então o calor passa do ambiente para o picolé, que derrete 🍦. Nos outros casos, o calor sai do café, da panela e da mão."},
{n:"d",t:"Energia térmica e calor",q:"Por que dizemos que o calor é 'energia em trânsito'?",a:["Porque fica guardado para sempre dentro dos objetos","Porque é energia passando de um corpo a outro","Porque viaja sempre do frio para o quente","Porque só existe dentro do fogo"],c:1,e:"Calor é o nome da energia térmica enquanto ela está passando de um corpo mais quente para um mais frio. Quando as temperaturas se igualam, essa passagem para."},
{n:"d",t:"Efeitos do calor",q:"Por que um copo de vidro grosso pode trincar quando colocamos água fervendo nele de uma vez?",a:["O vidro derrete","A água é pesada demais","O vidro dilata de forma desigual e racha","A água quente congela o vidro"],c:2,e:"A parte de dentro do copo esquenta e dilata rápido, mas a de fora continua fria. Essa diferença força o vidro, que acaba trincando 🥛."},
{n:"d",t:"Efeitos do calor",q:"Uma panela com água está fervendo há 10 minutos, ao nível do mar. Se aumentarmos o fogo, a temperatura da água...",a:["Sobe para 150 °C","Cai para 50 °C","Sobe para 200 °C","Continua em 100 °C, mas ferve mais rápido"],c:3,e:"Enquanto ferve, a água fica parada em 100 °C (ao nível do mar). Mais fogo só faz ela virar vapor mais depressa, mas não a esquenta mais 🍲."},
{n:"d",t:"Efeitos do calor",q:"Num copo há gelo derretendo na água. Enquanto ainda existe gelo e a água é mexida, qual é a temperatura aproximada da mistura?",a:["Cerca de 0 °C","Cerca de 25 °C","Cerca de 100 °C","Cerca de 50 °C"],c:0,e:"Enquanto o gelo derrete, o calor recebido é usado para a fusão, e a mistura de gelo e água fica perto de 0 °C. Só depois que todo o gelo derrete a temperatura sobe 🧊."},
{n:"d",t:"Efeitos do calor",q:"Em cidades muito altas, como La Paz, na Bolívia, a água ferve abaixo de 100 °C. Isso mostra que...",a:["Os termômetros de lá estão quebrados","A ebulição depende da altitude do lugar","O fogo de lá é mais fraco","A água de lá é diferente"],c:1,e:"Os 100 °C valem para o nível do mar. Em lugares bem altos, a água ferve em temperatura menor (em La Paz, perto de 87 °C) 🏔️."},
{n:"d",t:"Efeitos do calor",q:"Na sequência gelo → água → vapor, quais são os nomes das duas mudanças de estado?",a:["Solidificação e condensação","Condensação e fusão","Fusão e vaporização","Vaporização e solidificação"],c:2,e:"Gelo → água é fusão (sólido para líquido). Água → vapor é vaporização (líquido para gasoso), que pode ser evaporação ou ebulição."},
{n:"d",t:"Efeitos do calor",q:"Na tampa de uma panela com água fervendo aparecem gotinhas por dentro. Quais mudanças de estado aconteceram, em ordem?",a:["Fusão e depois solidificação","Condensação e depois fusão","Solidificação e depois vaporização","Vaporização e depois condensação"],c:3,e:"Primeiro a água vira vapor (vaporização). Depois o vapor encosta na tampa, mais fria, e volta a ser líquido (condensação) 💧."},
{n:"d",t:"Efeitos do calor",q:"Um engenheiro esqueceu as juntas de dilatação numa ponte de concreto. O que pode acontecer num verão bem quente?",a:["O concreto dilata, empurra e pode rachar","O concreto encolhe e a ponte fica mais curta","A ponte derrete","Nada, o concreto não muda com o calor"],c:0,e:"No calor, o concreto dilata. Sem espaço para crescer, as partes se empurram e podem rachar ou entortar. Por isso as juntas são tão importantes 🌉."},
{n:"d",t:"Efeitos do calor",q:"Qual é a diferença entre evaporação e ebulição?",a:["Evaporação só ocorre a 100 °C; ebulição a qualquer temperatura","Evaporação é lenta, na superfície; ebulição é rápida, com bolhas","São a mesma coisa com nomes diferentes","Evaporação vira gelo; ebulição vira vapor"],c:1,e:"Evaporação: a água vira vapor devagar, pela superfície, em qualquer temperatura (roupa no varal). Ebulição: é rápida, com bolhas, a 100 °C ao nível do mar (água fervendo)."},
{n:"d",t:"Efeitos do calor",q:"Por que a roupa seca mais rápido num dia quente e com vento do que num dia frio e sem vento?",a:["O vento empurra a água para dentro do tecido","O sol transforma a água da roupa em gelo","Calor e vento aceleram a evaporação","No dia frio a água ferve mais depressa"],c:2,e:"Com mais calor, a água evapora mais rápido, e o vento leva embora o vapor de perto da roupa. Por isso dia quente e com vento é ótimo para secar roupa 👕🌬️."},
{n:"d",t:"Efeitos do calor",q:"Uma tampa de metal de um pote de vidro está emperrada. O que acontece se colocarmos o pote no congelador, em vez de usar água quente?",a:["A tampa dilata e solta fácil","Nada muda, pois o frio não afeta os materiais","O vidro derrete","A tampa encolhe e aperta mais"],c:3,e:"No frio, o metal contrai (encolhe) mais que o vidro, e a tampa fica ainda mais apertada. Para soltar, o certo é aquecer a tampa 🫙."},
{n:"d",t:"Condutores e isolantes de calor",q:"Por que a colher de metal esquenta no chocolate quente e a de madeira quase não esquenta?",a:["O metal conduz bem o calor; a madeira é isolante","A madeira é mais gelada","O metal fabrica calor","A madeira é mais pesada"],c:0,e:"O metal é bom condutor: o calor do chocolate sobe rápido até o cabo. A madeira é isolante: o calor passa por ela muito devagar 🥄."},
{n:"d",t:"Condutores e isolantes de calor",q:"Numa sala a 25 °C, uma barra de metal e um pedaço de madeira estão lá há horas. Ao tocar, o metal parece mais frio. Por quê?",a:["O metal está numa temperatura mais baixa","O metal tira calor da mão mais rápido","A madeira produz calor próprio","O metal solta frio na mão"],c:1,e:"Os dois estão a 25 °C! Mas o metal conduz o calor da nossa mão muito mais rápido, e por isso a mão sente frio. A madeira, isolante, tira calor bem devagar."},
{n:"d",t:"Condutores e isolantes de calor",q:"Se embrulharmos um picolé num cobertor de lã, o que acontece?",a:["Ele derrete mais rápido, pois a lã esquenta","Ele congela ainda mais","Ele derrete mais devagar, pois a lã isola","Ele derrete igual, sem nenhuma diferença"],c:2,e:"A lã não produz calor: ela é isolante. Ela dificulta a chegada do calor do ambiente até o picolé, que derrete mais devagar 🍦🧣."},
{n:"d",t:"Condutores e isolantes de calor",q:"Duas canecas com chocolate quente: uma de metal e outra de porcelana grossa. Qual esquenta mais a mão de quem segura?",a:["A de porcelana, que conduz melhor o calor","As duas esquentam exatamente igual","A de porcelana, pois é isolante","A de metal, que conduz melhor o calor"],c:3,e:"O metal é melhor condutor de calor que a porcelana. Por isso a caneca de metal passa o calor do chocolate para a mão bem mais rápido ☕."},
{n:"d",t:"Condutores e isolantes de calor",q:"Por que a mesma garrafa térmica que mantém o café quente também mantém um suco gelado?",a:["Dificulta a entrada de calor de fora","Ela tem um motorzinho que fabrica frio","Ela guarda o frio do suco nas paredes","O espelho de dentro gela o suco"],c:0,e:"A garrafa térmica dificulta a passagem do calor nos dois sentidos: o calor do café não sai, e o calor de fora não entra no suco 🧃☕."},
{n:"d",t:"Condutores e isolantes de calor",q:"No mesmo quarto, por que o piso de cerâmica parece mais frio para os pés descalços do que o tapete?",a:["A cerâmica está numa temperatura bem mais baixa que o tapete","A cerâmica conduz o calor dos pés mais rápido","O tapete produz calor","A cerâmica produz frio"],c:1,e:"Piso e tapete estão na mesma temperatura. A cerâmica conduz o calor dos pés mais rápido; o tapete, cheio de ar entre os fios, é isolante 🦶."},
{n:"d",t:"Condutores e isolantes de calor",q:"Os inuítes, povo que vive em regiões geladas, constroem iglus de neve. Qual propriedade da neve compactada torna isso uma boa ideia?",a:["Ela conduz bem o calor","Ela produz calor","Ela tem ar preso e é isolante","Ela é transparente"],c:2,e:"A neve compactada tem muitas bolsinhas de ar presas, o que a torna isolante. Ela dificulta a saída do calor de dentro do iglu ❄️."},
{n:"d",t:"Condutores e isolantes de calor",q:"Gustavo colocou cubos de gelo iguais em três copos: um de alumínio, um de vidro e um de isopor. Em qual o gelo deve durar mais?",a:["No de alumínio","No de vidro","Igual nos três","No de isopor"],c:3,e:"O isopor é o melhor isolante dos três: dificulta a chegada do calor do ambiente até o gelo. O alumínio, por ser metal, deixa o calor entrar mais rápido."},
{n:"d",t:"Condutores e isolantes de calor",q:"Se o cabo de uma panela fosse feito de ferro, em vez de plástico, o que aconteceria ao cozinhar?",a:["Esquentaria e queimaria a mão","Ficaria gelado, pois o ferro é isolante","O cabo derreteria na hora","A comida demoraria mais para cozinhar"],c:0,e:"O ferro é bom condutor: o calor do fogo passaria pela panela até o cabo, que ficaria muito quente. Por isso os cabos são de plástico ou madeira 🍳."},
{n:"d",t:"Condutores e isolantes de calor",q:"Por que, no frio, vestir várias camadas de roupa costuma manter o corpo mais aquecido do que uma só peça?",a:["Cada camada de roupa fabrica um pouco de calor","O ar preso entre elas ajuda a isolar","O frio fica preso entre as camadas","O ar é um ótimo condutor de calor"],c:1,e:"Entre as camadas fica ar preso, e o ar parado é um ótimo isolante. Assim, o calor do nosso corpo escapa mais devagar 🧥."},
{n:"d",t:"Energia elétrica no dia a dia",q:"Os fios dos postes ficam presos em peças de vidro ou de porcelana. Por quê?",a:["Conduzem muito bem a eletricidade","Deixam o poste mais bonito","São isolantes elétricos","Esquentam os fios no inverno"],c:2,e:"Vidro e porcelana são isolantes elétricos. Eles impedem que a eletricidade dos fios passe para o poste e chegue ao chão ⚡."},
{n:"d",t:"Energia elétrica no dia a dia",q:"Por que o eletricista usa luvas de borracha e ferramentas com cabo de plástico?",a:["Borracha e plástico conduzem bem a eletricidade","Para as ferramentas ficarem mais leves","Para não sujar as mãos de graxa","Borracha e plástico são isolantes elétricos"],c:3,e:"Borracha e plástico são isolantes elétricos: dificultam a passagem da corrente e protegem o eletricista de choques 🧤🔧."},
{n:"d",t:"Energia elétrica no dia a dia",q:"Num circuito com pilha, lâmpada e interruptor, a lâmpada não acende mesmo com o interruptor ligado e os fios bem presos. Qual pode ser a causa?",a:["A pilha está descarregada","O circuito está fechado","Os fios são de cobre","O interruptor é de plástico por fora"],c:0,e:"Se tudo está ligado certinho, pode estar faltando energia: a pilha descarregada não faz a corrente passar. (Uma lâmpada queimada também poderia ser a causa.) 🔋"},
{n:"d",t:"Energia elétrica no dia a dia",q:"Qual conjunto de atitudes ajuda a economizar energia elétrica?",a:["Banho longo, TV ligada sem ninguém e geladeira aberta","Banho curto, luz apagada ao sair e geladeira bem fechada","Luz acesa de dia, banho curto e ferro ligado sem uso","Carregador sempre na tomada e luzes acesas a noite toda"],c:1,e:"Banhos curtos, apagar a luz ao sair e manter a geladeira bem fechada evitam desperdício. Nas outras opções sempre há alguma atitude que desperdiça energia 💡."},
{n:"d",t:"Energia elétrica no dia a dia",q:"Comparando as usinas de energia, qual afirmação está correta?",a:["A termelétrica não polui nada","A hidrelétrica funciona com a força do vento","A eólica usa vento, sem queimar nada","A solar funciona queimando carvão"],c:2,e:"A usina eólica gera eletricidade com o vento, sem queimar combustível. A termelétrica queima combustíveis e polui o ar; a hidrelétrica usa a água dos rios."},
{n:"d",t:"Energia elétrica no dia a dia",q:"Sobre a usina nuclear, como a de Angra dos Reis (RJ), qual afirmação é correta?",a:["Usa a força do vento","É renovável como a solar","Funciona queimando lenha","Usa urânio, que não é renovável, e gera lixo radioativo"],c:3,e:"A usina nuclear usa o urânio, um material que não se renova, e produz lixo radioativo, que precisa ser guardado com muito cuidado ☢️."},
{n:"d",t:"Energia elétrica no dia a dia",q:"Depois de uma tempestade, Gustavo vê um fio de poste caído na calçada. Qual é a atitude correta?",a:["Ficar longe e chamar um adulto","Afastar o fio com o pé","Pegar o fio com a mão seca","Encostar nele com um galho"],c:0,e:"Um fio caído pode estar com eletricidade e causar um choque grave. O certo é ficar longe e pedir para um adulto avisar a companhia de energia ⚠️."},
{n:"d",t:"Energia elétrica no dia a dia",q:"Gustavo quer testar se um objeto conduz eletricidade: ele o coloca no lugar de um pedaço de fio do circuito. Com qual objeto a lâmpada vai acender?",a:["Uma borracha escolar","Um clipe de metal","Um palito de madeira seco","Um canudo de plástico"],c:1,e:"O clipe é de metal, que conduz eletricidade, então o circuito fecha e a lâmpada acende 📎. Borracha, madeira seca e plástico são isolantes."},
];
